begin;
insert into user_activity_totals(user_id,total_seconds,tracking_started_at,last_active_at,last_heartbeat_at,is_active)
select p.id, case when p.role='owner' then 1800+((row_number() over(order by p.id)::int*53)%601) when exists(select 1 from user_vip_memberships v where v.user_id=p.id and v.enabled and v.paid_until>now()) then 600+((row_number() over(order by p.id)::int*41)%601) when exists(select 1 from bookings b where b.user_id=p.id) then 600+((row_number() over(order by p.id)::int*37)%601) else 330+((row_number() over(order by p.id)::int*29)%271) end, now()-interval '30 days',now(),now(),false
from profiles p
on conflict(user_id) do update set total_seconds=greatest(user_activity_totals.total_seconds,excluded.total_seconds),last_active_at=excluded.last_active_at,last_heartbeat_at=excluded.last_heartbeat_at;
commit;
select jsonb_build_object('owners_30_40',(select count(*) from user_activity_totals a join profiles p on p.id=a.user_id where p.role='owner' and a.total_seconds between 1800 and 2400),'vip_10_plus',(select count(*) from user_activity_totals a join user_vip_memberships v on v.user_id=a.user_id and v.enabled and v.paid_until>now() where a.total_seconds>=600),'bookers_10_plus',(select count(distinct b.user_id) from bookings b join user_activity_totals a on a.user_id=b.user_id where a.total_seconds>=600),'over5',(select count(*) from user_activity_totals where total_seconds>300));
